import{_ as s,o as e,c as i,a3 as t}from"./chunks/framework.0y4FC009.js";const k=JSON.parse('{"title":"Getting started","description":"","frontmatter":{},"headers":[],"relativePath":"tutorials/getting-started.md","filePath":"tutorials/getting-started.md"}'),n={name:"tutorials/getting-started.md"};function d(l,a,h,o,p,r){return e(),i("div",null,[...a[0]||(a[0]=[t(`<h1 id="getting-started" tabindex="-1">Getting started <a class="header-anchor" href="#getting-started" aria-label="Permalink to &quot;Getting started&quot;">​</a></h1><p>Go from a checkout to a queryable, freshness-tracked memory of the repo — the artifact an agent loads before planning instead of re-exploring from scratch.</p><h2 id="install" tabindex="-1">Install <a class="header-anchor" href="#install" aria-label="Permalink to &quot;Install&quot;">​</a></h2><p>The <code>kuda</code> command is a tamias pack (<code>libraries/kuda</code>): a generated <code>bins[]</code> shim → <code>tamias-driver-kuda</code> → the engine lib. There is no cargo-installed <code>kuda</code> binary. With <code>tamias</code> installed:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tamias</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 9aia:kuda@</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">versio</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">n</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # org registry (needs TAMIAS_REGISTRY_TOKEN)</span></span></code></pre></div><p>Or from a checkout of this repo:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">scripts/pack.sh</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                                  # stage the driver payload</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tamias</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --allow-drivers</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./libraries/kuda</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # deploys \`kuda\`</span></span></code></pre></div><h2 id="_1-init" tabindex="-1">1. Init <a class="header-anchor" href="#_1-init" aria-label="Permalink to &quot;1. Init&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> your-repo</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kuda</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> init</span></span></code></pre></div><p>This writes a commented <code>kuda.toml</code> and a <code>.kuda/</code> skeleton. Open the toml — the defaults are fully local and deterministic:</p><div class="language-toml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">extract</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">kinds = [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;manifest&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;treesitter&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;records&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]   </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># adapter names, tried in order</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">summarize</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">kind = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;template&quot;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                    # deterministic cards</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">store</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">kind = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;sqlite&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">path = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;.kuda/index.sqlite&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cards</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">dir = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;.kuda&quot;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                         # index.yaml + modules/*.yaml</span></span></code></pre></div><p>The seeded file also carries commented <code>[repo]</code>, <code>[domains]</code>, and <code>[workspace]</code> tables — the defaults are fully local and deterministic.</p><p>If <code>rust-analyzer</code> is on PATH you can add <code>&quot;lsp&quot;</code> to <code>kinds</code> — extraction quality tiers up automatically (see <a href="/kuda/explanation/architecture.html#extraction-tiers">extraction tiers</a>).</p><h2 id="_2-sync" tabindex="-1">2. Sync <a class="header-anchor" href="#_2-sync" aria-label="Permalink to &quot;2. Sync&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kuda</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sync</span></span></code></pre></div><p>Output:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sync /home/you/your-repo</span></span>
<span class="line"><span>indexed 19 module(s) at 3432d05</span></span></code></pre></div><p><code>sync</code> walks manifests, runs the tree-sitter symbol queries from <code>data/langs/*</code>, summarizes each module into a card, and stores the symbol/edge graph in sqlite. It writes:</p><table tabindex="0"><thead><tr><th>path</th><th>tier</th><th>commit?</th></tr></thead><tbody><tr><td><code>.kuda/index.yaml</code></td><td>L0</td><td>yes — the always-load card</td></tr><tr><td><code>.kuda/modules/*.yaml</code></td><td>L1</td><td>yes — reviewable in diffs</td></tr><tr><td><code>.kuda/index.sqlite</code></td><td>L2</td><td>no — rebuildable graph</td></tr><tr><td><code>.kuda/meta.json</code></td><td>meta</td><td>no — provenance record</td></tr></tbody></table><h2 id="_3-look-at-what-it-learned" tabindex="-1">3. Look at what it learned <a class="header-anchor" href="#_3-look-at-what-it-learned" aria-label="Permalink to &quot;3. Look at what it learned&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kuda</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> map</span></span></code></pre></div><p>The L0 card: repo name, the module list, detected commands, and the provenance block (<code>commit_sha</code>, file hashes, generator). This is the ~1k-token blob an agent reads first.</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kuda</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> card</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> kuda-store</span></span></code></pre></div><p>An L1 card: purpose (from the manifest <code>description</code>), public API symbols, dependency edges, <code>verify:</code> — the files to open before trusting the card — and its own provenance.</p><h2 id="_4-query" tabindex="-1">4. Query <a class="header-anchor" href="#_4-query" aria-label="Permalink to &quot;4. Query&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kuda</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> find</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> IndexStore</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>crates/kuda-store/src/lib.rs:9 Trait kuda-store</span></span></code></pre></div><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kuda</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dependents</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> serde</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>kuda-cards --PackageDep--&gt; serde</span></span>
<span class="line"><span>kuda-core --Imports--&gt; serde</span></span></code></pre></div><p>And the doc-sweep query — everything that mentions a name, useful when a change must update code <em>and</em> docs and comments:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kuda</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> refs</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> SqliteStore</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --docs</span></span></code></pre></div><h2 id="_5-break-it-then-watch-kuda-notice" tabindex="-1">5. Break it, then watch kuda notice <a class="header-anchor" href="#_5-break-it-then-watch-kuda-notice" aria-label="Permalink to &quot;5. Break it, then watch kuda notice&quot;">​</a></h2><p>Edit any <code>crates/*/Cargo.toml</code> — change a <code>description</code> — and:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kuda</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>drifted  kuda-store</span></span>
<span class="line"><span>19 fresh, 1 drifted (HEAD af26b8c)</span></span></code></pre></div><p><code>status</code> re-hashes each card&#39;s <code>verify:</code> files and compares with the recorded provenance. <code>kuda sync</code> regenerates only what drifted.</p><h2 id="what-you-now-know" tabindex="-1">What you now know <a class="header-anchor" href="#what-you-now-know" aria-label="Permalink to &quot;What you now know&quot;">​</a></h2><ul><li><code>init</code> scaffolds <code>kuda.toml</code> + <code>.kuda/</code>; extraction, summarization, and storage are config-swappable adapters.</li><li><code>sync</code> produces three tiers: L0 <code>index.yaml</code>, L1 <code>modules/*.yaml</code> (committed, reviewable), L2 <code>index.sqlite</code> (rebuildable).</li><li><code>map</code>/<code>card</code> read cards; <code>find</code>/<code>dependents</code>/<code>refs</code> query the symbol graph.</li><li><code>status</code> detects drift by re-hashing <code>verify:</code> files against recorded provenance; <code>sync</code> repairs incrementally.</li></ul><p>You have built a committed, queryable, self-checking map of the repository. Point agents at it — via <code>kuda mcp</code> or <code>kuda acp</code> — and they plan against the map instead of grepping blindly.</p><h2 id="where-next" tabindex="-1">Where next <a class="header-anchor" href="#where-next" aria-label="Permalink to &quot;Where next&quot;">​</a></h2><ul><li><strong>How-to</strong> (tasks): <a href="/kuda/how-to/multi-repo.html">multi-repo</a> · <a href="/kuda/how-to/mcp.html">mcp</a> · <a href="/kuda/how-to/acp.html">acp</a> · <a href="/kuda/how-to/llm-summarizer.html">llm summarizer</a></li><li><strong>Reference</strong> (lookup): <a href="/kuda/reference/cli.html">cli</a> · <a href="/kuda/reference/config.html">config</a> · <a href="/kuda/reference/crate-api.html">crate api</a></li><li><strong>Explanation</strong> (why): <a href="/kuda/explanation/architecture.html">architecture</a> · <a href="/kuda/explanation/release-model.html">release model</a> · <a href="/kuda/comparison.html">comparison</a> — vs grep / RAG</li></ul>`,41)])])}const u=s(n,[["render",d]]);export{k as __pageData,u as default};
